import{_ as o,c as l,o as t,ag as i}from"./chunks/framework.DPDPlp3K.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"shopify/Shopify Slate.md","filePath":"shopify/Shopify Slate.md"}'),a={name:"shopify/Shopify Slate.md"};function s(r,e,h,p,n,S){return t(),l("div",null,e[0]||(e[0]=[i('<h2 id="标题备选" tabindex="-1">标题备选 <a class="header-anchor" href="#标题备选" aria-label="Permalink to &quot;标题备选&quot;">​</a></h2><ol><li>Shopify 开发实战：Shopify Slate 已弃用？迁移到 Shopify CLI 一篇讲清楚</li><li>手把手梳理 Shopify：Shopify Slate 已弃用？迁移到 Shopify CLI 的关键用法和避坑点</li><li>做 Shopify 项目别只会改主题，这篇带你搞懂 Shopify Slate 已弃用？迁移到 Shopify CLI</li></ol><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>这篇文章适合 Shopify 主题和应用开发者，围绕「Shopify Slate 已弃用？迁移到 Shopify CLI」梳理核心概念、配置路径和实战注意点，方便项目中快速对照。</p><h2 id="正文" tabindex="-1">正文 <a class="header-anchor" href="#正文" aria-label="Permalink to &quot;正文&quot;">​</a></h2><p>哈喽大家好👋 我是程序🦍kk。把复杂知识掰成大白话讲明白，是我一直以来的小追求✨；<strong>打好基础才能稳步进阶</strong>，是我始终秉持的学习理念～</p><blockquote><p>📢 我搭建了5000人程序猿专属学习交流群 群内会同步前端开发/全栈开发/Web3开发/远程工作等干货资源 关注我并回复 <strong>加群</strong> ，就能加入交流圈啦🚀</p></blockquote><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p><strong>Shopify 项目最容易卡住的地方，往往不是“会不会写代码”，而是主题、应用和后台配置之间的关系没理顺。</strong></p><p>很多同学做 Shopify 开发时，会同时碰到 Liquid、主题目录、Checkout、Metafields、应用后台、性能优化这些概念。单独看不难，放到真实项目里就容易散。</p><p>这篇围绕「Shopify Slate 已弃用？迁移到 Shopify CLI」把原始笔记整理成更适合阅读和复用的版本，适合做主题开发、应用开发或者接手 Shopify 项目时快速对照。</p><h2 id="shopify-实战整理" tabindex="-1">Shopify 实战整理 <a class="header-anchor" href="#shopify-实战整理" aria-label="Permalink to &quot;Shopify 实战整理&quot;">​</a></h2><p>下面进入 Shopify 相关内容整理。建议大家边看边对照自己的店铺、主题代码和应用后台，很多问题只有放到真实配置里才容易看清楚。</p><p>如果你正在做 Shopify 项目，可以重点留意主题代码、后台配置、应用能力和官方限制之间的边界，很多线上问题都出在这些交界处。</p><h2 id="什么是-shopify-slate" tabindex="-1">什么是 Shopify Slate？ <a class="header-anchor" href="#什么是-shopify-slate" aria-label="Permalink to &quot;什么是 Shopify Slate？&quot;">​</a></h2><p><strong>简短回答：</strong><strong>Shopify Slate</strong> 是 Shopify 很早期推出的一套 <strong>主题开发脚手架（toolkit / scaffold）与构建工具</strong>，用于本地开发 Shopify 主题（支持 Sass、Webpack 打包、热更新等）。 它现在已经 <strong>不再维护 / 已被弃用</strong>，官方推荐使用的现代工具是 <strong><a href="https://shopify.dev/docs/storefronts/themes/tools/cli" target="_blank" rel="noreferrer">Shopify CLI for themes</a></strong>。</p><hr><h2 id="_1-slate-是干什么的" tabindex="-1">1. Slate 是干什么的？ <a class="header-anchor" href="#_1-slate-是干什么的" aria-label="Permalink to &quot;1. Slate 是干什么的？&quot;">​</a></h2><p>在 Online Store 2.0 和 Shopify CLI 之前，开发者要做这些事：</p><ul><li>本地开发主题（Sass 编译、ES6 转 ES5、打包 JS、压缩资源）</li><li>上传主题到店铺</li><li>预览修改</li></ul><p>Slate 作为一个「主题开发工具集」，主要提供了：</p><ol><li><strong>主题脚手架</strong><ul><li>提供一套「入门主题」结构，可以作为新项目的基础。</li></ul></li><li><strong>构建管线（构建系统）</strong><ul><li>使用 Gulp / Webpack 等工具： <ul><li>编译 SCSS / Sass</li><li>打包 / 压缩 JS</li><li>处理静态资源</li></ul></li></ul></li><li><strong>与 Shopify 主题 API 集成</strong><ul><li>类似早期 Theme Kit：可以把本地改动上传到 Shopify 主题上去。</li></ul></li></ol><p>当时的典型工作流：</p><ul><li><code>slate theme &lt;something&gt;</code> 初始化项目</li><li>本地开发（写 Sass、ES6 JS）</li><li>Slate 负责打包输出到 <code>dist/</code>，再同步到店铺对应的主题</li></ul><hr><h2 id="_2-为什么现在感觉很少听到-slate" tabindex="-1">2. 为什么现在感觉很少听到 Slate？ <a class="header-anchor" href="#_2-为什么现在感觉很少听到-slate" aria-label="Permalink to &quot;2. 为什么现在感觉很少听到 Slate？&quot;">​</a></h2><p>原因：<strong>Slate 已经被官方弃用 / 停止维护了</strong>。</p><p>Shopify 后续推出并不断升级的工具链是：</p><ul><li><strong>Theme Kit（早期主力）</strong>：命令行同步主题文件，但没有完整的构建功能。</li><li><strong><a href="https://shopify.dev/docs/storefronts/themes/tools/cli" target="_blank" rel="noreferrer">Shopify CLI for themes</a></strong>： <ul><li>支持「开发主题（development theme）」</li><li>内置本地开发服务器</li><li>热更新 Section 和 CSS</li><li>一体化支持 Online Store 2.0 的主题开发</li><li>与 GitHub 集成、Theme Check 等</li></ul></li></ul><p>官方现在的推荐路线基本都是：</p><blockquote><p><strong>Shopify CLI + 自己的前端构建工具（例如 Vite / Webpack / esbuild）</strong> 而不再使用 Slate。</p></blockquote><hr><h2 id="_3-现在做主题开发-用什么代替-slate" tabindex="-1">3. 现在做主题开发，用什么代替 Slate？ <a class="header-anchor" href="#_3-现在做主题开发-用什么代替-slate" aria-label="Permalink to &quot;3. 现在做主题开发，用什么代替 Slate？&quot;">​</a></h2><p><strong>官方推荐工具：</strong></p><ol><li><p><strong>Shopify CLI for themes</strong> 文档链接：<a href="https://shopify.dev/docs/storefronts/themes/tools/cli" target="_blank" rel="noreferrer">Shopify CLI for themes</a></p><p>主要能力：</p><ul><li><code>shopify theme dev</code>：本地开发 + 热更新</li><li><code>shopify theme push</code>：推送主题到店铺</li><li><code>shopify theme pull</code>：从店铺拉回主题代码</li><li>支持多环境 <code>shopify.theme.toml</code>（dev / staging / prod）</li><li>集成 Theme Check（Lint Liquid / JSON 配置）</li></ul></li><li><p><strong>自定义构建工具（取代 Slate 构建层）</strong></p><p>Slate 以前帮你做的：</p><ul><li>Sass 编译</li><li>ES6 打包</li><li>压缩 / hash</li></ul><p>现在推荐自己用：</p><ul><li><strong>Vite / Webpack / esbuild / Rollup</strong> 等前端工具管理 <code>assets/</code> 目录的构建产物</li><li>输出文件放入 <code>assets</code> 下，由 Shopify CLI 推送到店铺</li></ul><p>一个典型工作流示意（代替 Slate）：</p><p>终端 1：跑前端构建（比如 Vite / Webpack watch）</p><p>终端 2：跑 Shopify CLI 的 dev server</p><p>当你改 JS/CSS 时：</p><ul><li>构建工具输出到 <code>assets/xxx.js</code> / <code>assets/xxx.css</code></li><li>Shopify CLI 检测到文件变化 → 热更新 / 自动刷新浏览器</li></ul></li></ol><hr><h2 id="_4-如果你看到旧项目在用-slate-怎么办" tabindex="-1">4. 如果你看到旧项目在用 Slate，怎么办？ <a class="header-anchor" href="#_4-如果你看到旧项目在用-slate-怎么办" aria-label="Permalink to &quot;4. 如果你看到旧项目在用 Slate，怎么办？&quot;">​</a></h2><p>很多老项目可能：</p><ul><li>仓库里有 <code>slate.config.js</code>、<code>slate-tools</code> 等依赖。</li><li>使用的是 <code>src/</code> 源码目录 + <code>dist/</code> 输出目录结构。</li></ul><p><strong>迁移思路：</strong></p><ol><li><strong>保持目录结构，移除 Slate 相关依赖</strong></li><li>新建自己的构建配置（例如 Vite / Webpack）： <ul><li>把 <code>src/</code> 里的 Sass/TS/ES6 编译到 <code>dist/</code> 或直接到 <code>assets/</code></li></ul></li><li>使用 Shopify CLI 来： <ul><li>本地开发：<code>shopify theme dev</code></li><li>部署：<code>shopify theme push</code></li></ul></li></ol><p>官方有 CLI 迁移相关文档（虽然不是专门针对 Slate，但理念一致）：</p><ul><li><a href="https://shopify.dev/docs/storefronts/themes/tools/cli/migrate" target="_blank" rel="noreferrer">Migrate to Shopify CLI 3.x</a></li></ul><hr><h2 id="_5-总结" tabindex="-1">5. 总结 <a class="header-anchor" href="#_5-总结" aria-label="Permalink to &quot;5. 总结&quot;">​</a></h2><ul><li><strong>Shopify Slate</strong> = 早期的 Shopify 主题开发 toolkit（脚手架 + 构建工具 + 上传同步）。</li><li>已经 <strong>停止维护 / 弃用</strong>。</li><li>现在官方推荐： <ul><li>使用 <strong><a href="https://shopify.dev/docs/storefronts/themes/tools/cli" target="_blank" rel="noreferrer">Shopify CLI for themes</a></strong> 作为主题开发的主要 CLI 工具。</li><li>自己选用现代前端构建工具（Vite / Webpack / 等）替代 Slate 的构建功能。</li></ul></li></ul><hr><p>如果你现在手上有一个「正在用 Slate 的老主题项目」，可以把目录结构（文件列表）贴一段出来，我可以帮你设计一份<strong>从 Slate 迁移到 Shopify CLI + Vite/Webpack 的具体步骤与配置示例</strong>。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>好啦，今天的分享就到这里！</p><p>💬 互动时间：</p><p>你现在做 Shopify 更常遇到的是主题开发、Checkout 定制、应用接入，还是性能优化？如果你在「Shopify Slate 已弃用？迁移到 Shopify CLI」上踩过坑，也可以把场景留言出来。</p><p>最后，感谢你看到这里👏</p><p>如果喜欢这篇内容，不妨顺手给小编安排一波👇 <strong>点赞</strong>👍｜<strong>转发</strong>📲｜<strong>推荐</strong>❤️｜<strong>评论</strong>📣</p><p>要是想第一时间蹲到新内容推送，记得给我点个<strong>星标</strong>⭐️</p><p>更多干货内容正在持续填坑中，咱们下期见👋</p><h2 id="标签建议" tabindex="-1">标签建议 <a class="header-anchor" href="#标签建议" aria-label="Permalink to &quot;标签建议&quot;">​</a></h2><p>Shopify、主题开发、独立站</p>',58)]))}const c=o(a,[["render",s]]);export{d as __pageData,c as default};
